     1	import { type Customer, type Item, quote } from "./claim-office.js";
     2	import { type ClaimSettlement, type Incident, type Policy, policyFor, settle } from "./claim.js";
     3	
     4	export interface QuoteStep {
     5	  readonly op: "quote";
     6	  readonly items: readonly Item[];
     7	}
     8	
     9	export interface ClaimStep {
    10	  readonly op: "claim";
    11	  readonly policy: number;
    12	  readonly incident: Incident;
    13	}
    14	
    15	export type Step = QuoteStep | ClaimStep;
    16	
    17	export interface Scenario {
    18	  readonly customer: Customer;
    19	  readonly steps: readonly Step[];
    20	}
    21	
    22	export interface QuoteResult {
    23	  readonly premium: number;
    24	}
    25	
    26	export type StepResult = QuoteResult | ClaimSettlement;
    27	
    28	// Steps are processed in order; each completed quote step becomes a contract in
    29	// the customer's history, which the next quote step is priced against.
    30	export function runScenario(scenario: Scenario): StepResult[] {
    31	  let contracts = 0;
    32	  const results: StepResult[] = [];
    33	  // A policy stands for the rest of the scenario once its quote step creates it,
    34	  // and every later claim step naming that step index settles against the very
    35	  // same policy, not a copy of it. That shared identity is what gives successive
    36	  // claims one cap to deplete between them: the second of two 1500 G claims
    37	  // against a sword is paid the 600 G its predecessor left standing.
    38	  const standingPolicies = new Map<number, Policy>();
    39	  scenario.steps.forEach((step, stepIndex) => {
    40	    if (step.op === "quote") {
    41	      results.push({ premium: quote(scenario.customer, step.items, contracts) });
    42	      standingPolicies.set(stepIndex, policyFor(step.items));
    43	      contracts += 1;
    44	      return;
    45	    }
    46	    const policy = standingPolicies.get(step.policy);
    47	    if (policy === undefined) {
    48	      throw new Error(`step ${step.policy} did not create a policy`);
    49	    }
    50	    results.push(settle(policy, step.incident));
    51	  });
    52	  return results;
    53	}
=====CLAIM=====
     1	import { type Item, insuranceSumOf } from "./claim-office.js";
     2	
     3	const DEDUCTIBLE_PER_DAMAGE_ENTRY = 100;
     4	const PAYOUT_CAP_MULTIPLE = 2;
     5	const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
     6	const HIGH_ENCHANTMENT_REIMBURSEMENT_SHARE = 0.5;
     7	const UNREDUCED_REIMBURSEMENT_SHARE = 1;
     8	
     9	export interface Damage {
    10	  readonly itemType: string;
    11	  readonly amount: number;
    12	}
    13	
    14	export interface Incident {
    15	  readonly cause: string;
    16	  readonly damages: readonly Damage[];
    17	}
    18	
    19	// What the policy covers never changes, but how much of its cap is left does:
    20	// `remainingCap` is the office's running record of cap not yet paid out, and
    21	// `settle` depletes it in place. A policy is therefore a standing record that
    22	// outlives the claim being settled, and whoever holds one holds the cap's one
    23	// authoritative figure -- two claims given the same policy share its cap, two
    24	// given separately built policies do not.
    25	export interface Policy {
    26	  readonly items: readonly Item[];
    27	  readonly insuranceSum: number;
    28	  remainingCap: number;
    29	}
    30	
    31	export interface ClaimSettlement {
    32	  readonly payout: number;
    33	  readonly remainingCap: number;
    34	}
    35	
    36	// A damage entry names an insured item by type; the clauses that govern the
    37	// payout are properties of that insured item, not of the damage report. Looking
    38	// the item up in the policy is therefore also the office's coverage rule: a
    39	// damage entry naming a type the policy does not cover is refused rather than
    40	// settled, and the whole claim falls with it. An amulet damaged when only a
    41	// sword is insured is not a payout of zero, it is a rejection. The refusal
    42	// cannot be lifted out of the lookup -- an entry is uncovered precisely because
    43	// the policy holds no item of its type, so resolving and refusing are one
    44	// decision made once per entry.
    45	//
    46	// This one rule answers both halves of the spec's claim-side rejection bullet.
    47	// An amulet named when only a sword is insured and a "broomstick" named at all
    48	// are the same refusal here, because the register is consulted for a match and
    49	// neither finds one -- so an unknown type needs no separate check against the
    50	// office's price list. That asymmetry with the quote side is deliberate: a quote
    51	// is priced against the office's price list, which is what makes `broomstick`
    52	// unknown there (see `listedPriceFor`), whereas a claim is settled against one
    53	// policy, whose item register is the only authority on what it may name. A type
    54	// the MHPCO insures but this policy does not cover is refused just as flatly.
    55	//
    56	// What it resolves is which clauses govern a damage, not which physical item was
    57	// destroyed: with two swords insured, two sword damage entries resolve to the
    58	// same insured item, which is right because the clauses read only the item's
    59	// attributes and alike items share them. Counting entries against items insured
    60	// is a separate rejection rule, and this lookup deliberately does not make it --
    61	// it answers only whether the type is covered at all.
    62	function damagedItemFor(policy: Policy, damage: Damage): Item {
    63	  const damagedItem = policy.items.find((item) => item.type === damage.itemType);
    64	  if (damagedItem === undefined) {
    65	    throw new Error(`damaged item ${damage.itemType} is not covered by the policy`);
    66	  }
    67	  return damagedItem;
    68	}
    69	
    70	function roundPayoutInOfficesFavour(payout: number): number {
    71	  return Math.floor(payout);
    72	}
    73	
    74	export function policyFor(items: readonly Item[]): Policy {
    75	  const insuranceSum = insuranceSumOf(items);
    76	  return { items, insuranceSum, remainingCap: insuranceSum * PAYOUT_CAP_MULTIPLE };
    77	}
    78	
    79	// The share of the damage amount the office reimburses, decided by the clauses
    80	// that the damaged item triggers. Damage to an item with enchantment level >= 8
    81	// is reimbursed at 50 %; with no clause reducing it, the whole amount is
    82	// reimbursable. The share is taken before the deductible.
    83	//
    84	// There is deliberately no dragon-material branch here, and adding one would be
    85	// a mistake. The spec's clause "damage to items made of dragon material is fully
    86	// reimbursed" asks for exactly the share this function already yields by default,
    87	// so on its own it is indistinguishable from no clause at all (dragon sword,
    88	// enchantment 5, damage 800 -> 800 - 100 = 700, identical to a steel sword). The
    89	// only case where it meets another clause is enchantment >= 8, and there the spec
    90	// says the 50 % rule wins (dragon sword, enchantment 8 or 9, damage 1000 -> 400).
    91	// So the clause never changes a payout: it is subsumed by the unreduced share and
    92	// loses every conflict. `Item.material` is read by no rule for that reason.
    93	function reimbursableShareOf(damagedItem: Item): number {
    94	  return (damagedItem.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL
    95	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_SHARE
    96	    : UNREDUCED_REIMBURSEMENT_SHARE;
    97	}
    98	
    99	// One entry of the incident's `damages` array is one damage, and each one bears
   100	// its own deductible -- a single dragon attack that damages a sword and an amulet
   101	// deducts 100 G twice, not once.
   102	function reimbursementFor(damage: Damage, damagedItem: Item): number {
   103	  return damage.amount * reimbursableShareOf(damagedItem) - DEDUCTIBLE_PER_DAMAGE_ENTRY;
   104	}
   105	
   106	// Summing per entry is what makes the deductible per-entry: the incident as a
   107	// whole is never the unit the deductible is charged against.
   108	function desiredReimbursementFor(policy: Policy, incident: Incident): number {
   109	  return incident.damages.reduce(
   110	    (sum, damage) => sum + reimbursementFor(damage, damagedItemFor(policy, damage)),
   111	    0,
   112	  );
   113	}
   114	
   115	// The cap limits what a single claim pays out, and every payout consumes it:
   116	// successive claims against the same policy share one cap.
   117	function payoutLimitedToRemainingCap(desiredReimbursement: number, remainingCap: number): number {
   118	  return Math.min(desiredReimbursement, remainingCap);
   119	}
   120	
   121	function consumeCap(policy: Policy, payout: number): void {
   122	  policy.remainingCap -= payout;
   123	}
   124	
   125	function countByType(itemTypes: readonly string[]): Map<string, number> {
   126	  const counts = new Map<string, number>();
   127	  for (const itemType of itemTypes) {
   128	    counts.set(itemType, (counts.get(itemType) ?? 0) + 1);
   129	  }
   130	  return counts;
   131	}
   132	
   133	// A damage report states what was lost, so a negative amount is not a smaller
   134	// claim but an unreportable one.
   135	function refuseNegativeDamageAmounts(incident: Incident): void {
   136	  for (const damage of incident.damages) {
   137	    if (damage.amount < 0) {
   138	      throw new Error(`a damage amount cannot be negative, but ${damage.amount} was reported`);
   139	    }
   140	  }
   141	}
   142	
   143	// Each damage entry is a distinct damaged item, so the policy must insure at
   144	// least as many items of a type as the incident reports damages of it. Two
   145	// sword damages against a single insured sword is a rejected claim, not a
   146	// double payout on one sword.
   147	//
   148	// Counting types rather than matching entries to individual items is what lets
   149	// `damagedItemFor` settle every alike entry against the first item of its type:
   150	// once this rule has passed, the policy is known to hold enough alike items to
   151	// go round, and alike items carry identical clauses, so which one each entry is
   152	// assigned to cannot change a payout. The two rules are independent decisions
   153	// that meet here -- this one is not a shortcut for the lookup, it is the reason
   154	// the lookup need not be one.
   155	function refuseMoreDamagesThanInsured(policy: Policy, incident: Incident): void {
   156	  const insuredCounts = countByType(policy.items.map((item) => item.type));
   157	  for (const [itemType, damageCount] of countByType(
   158	    incident.damages.map((damage) => damage.itemType),
   159	  )) {
   160	    if (damageCount > (insuredCounts.get(itemType) ?? 0)) {
   161	      throw new Error(
   162	        `the policy insures fewer items of type ${itemType} than the claim reports damaged`,
   163	      );
   164	    }
   165	  }
   166	}
   167	
   168	// The order of the three cap-and-rounding steps is itself policy: the desired
   169	// reimbursement is first reduced to the remaining cap, the reduced figure is then
   170	// rounded in the office's favour, and the cap is consumed by that rounded payout
   171	// -- what the office actually books, not the fraction it computed. So the
   172	// remaining cap reported here stays a whole number across successive claims
   173	// against the same policy.
   174	//
   175	// Refusal comes first and is a different kind of decision from the figures that
   176	// follow: a refused claim has no payout, not a payout of zero. The whole claim
   177	// falls, which is why the refusal is made against the incident entire before any
   178	// entry is priced.
   179	//
   180	// The refusals stay a flat sequence here rather than gathering behind one
   181	// admission step, because they are not one criterion. A negative amount is
   182	// refused on the report alone -- no policy is consulted, and every policy the
   183	// office has written would refuse it alike -- whereas more damages of a type
   184	// than are insured is refused by reading the report against this policy's item
   185	// register. Either could change while the other stood: crediting negative
   186	// amounts would not touch the multiplicity rule, nor would paying one sword
   187	// twice touch the amount rule. A third refusal is not even in this sequence --
   188	// `damagedItemFor` refuses an uncovered type per entry, mid-pricing, because
   189	// there the refusal cannot be lifted out of the lookup. So a name spanning the
   190	// two calls below would both bundle independent policies and imply the office's
   191	// refusals end here, which they do not.
   192	export function settle(policy: Policy, incident: Incident): ClaimSettlement {
   193	  refuseNegativeDamageAmounts(incident);
   194	  refuseMoreDamagesThanInsured(policy, incident);
   195	  const payout = roundPayoutInOfficesFavour(
   196	    payoutLimitedToRemainingCap(desiredReimbursementFor(policy, incident), policy.remainingCap),
   197	  );
   198	  consumeCap(policy, payout);
   199	  return { payout, remainingCap: policy.remainingCap };
   200	}

  1	export interface Customer {
  2	  readonly yearsWithMHPCO: number;
  3	}
  4	
  5	export interface Item {
  6	  readonly type: string;
  7	  // Declared by the scenario input schema, but read by no rule: no premium rule
  8	  // mentions material, and the claim side's dragon-material clause is subsumed by
  9	  // its default share (see `reimbursableShareOf` in claim.ts).
 10	  readonly material?: string;
 11	  readonly cursed?: boolean;
 12	  readonly enchantment?: number;
 13	}
 14	
 15	const PROCESSING_FEE = 5;
 16	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
 17	const LOYALTY_DISCOUNT_RATE = 0.2;
 18	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
 19	const LONG_STANDING_MINIMUM_YEARS = 2;
 20	const CURSE_SURCHARGE_RATE = 0.5;
 21	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
 22	// The premium side's own threshold for "highly enchanted". The claim side sets a
 23	// separate, higher one for its reimbursement clause: the surcharge level and the
 24	// reimbursement level are independent policies that happen to read the same
 25	// item attribute, so neither may be derived from the other.
 26	const HIGH_ENCHANTMENT_SURCHARGE_LEVEL = 5;
 27	
 28	const MAIN_ITEM_BASE_PREMIUM_PRICE_LIST: Readonly<Record<string, number>> = {
 29	  sword: 100,
 30	  amulet: 60,
 31	  staff: 80,
 32	  potion: 40,
 33	};
 34	
 35	const COMPONENT_INSURANCE_VALUE = 250;
 36	
 37	const MAIN_ITEM_INSURANCE_VALUE_PRICE_LIST: Readonly<Record<string, number>> = {
 38	  sword: 1000,
 39	  amulet: 600,
 40	  staff: 800,
 41	  potion: 400,
 42	};
 43	
 44	const COMPONENT_TYPES: readonly string[] = ["rune", "moonstone"];
 45	const COMPONENT_BASE_PREMIUM = 25;
 46	const ALIKE_COMPONENTS_PER_BLOCK = 3;
 47	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
 48	
 49	function isComponent(item: Item): boolean {
 50	  return COMPONENT_TYPES.includes(item.type);
 51	}
 52	
 53	function mainItemsOf(items: readonly Item[]): readonly Item[] {
 54	  return items.filter((item) => !isComponent(item));
 55	}
 56	
 57	function componentsOf(items: readonly Item[]): readonly Item[] {
 58	  return items.filter(isComponent);
 59	}
 60	
 61	// Every MHPCO price list is also a register of what the office insures: a type
 62	// absent from it is refused rather than priced. That is why this takes the list
 63	// as a parameter instead of consulting one fixed table -- the base-premium and
 64	// insurance-value lists stay the independent policies they are (see
 65	// `MAIN_ITEM_INSURANCE_VALUE_PRICE_LIST`), and each refuses on its own entries.
 66	// The refusal cannot be lifted out of the lookup: a type is refused precisely
 67	// because the list it is being priced against has no figure for it, so checking
 68	// and pricing are one decision made once per list.
 69	function listedPriceFor(priceList: Readonly<Record<string, number>>, item: Item): number {
 70	  const listedPrice = priceList[item.type];
 71	  if (listedPrice === undefined) {
 72	    throw new Error(`the MHPCO does not insure items of type ${item.type}`);
 73	  }
 74	  return listedPrice;
 75	}
 76	
 77	function mainItemBasePremiumOf(item: Item): number {
 78	  return listedPriceFor(MAIN_ITEM_BASE_PREMIUM_PRICE_LIST, item);
 79	}
 80	
 81	// "Alike" means the same item type, not the same family: 2 runes + 1 moonstone
 82	// form no block.
 83	function countAlikeComponents(components: readonly Item[]): Map<string, number> {
 84	  const counts = new Map<string, number>();
 85	  for (const component of components) {
 86	    counts.set(component.type, (counts.get(component.type) ?? 0) + 1);
 87	  }
 88	  return counts;
 89	}
 90	
 91	function alikeComponentsBasePremiumOf(alikeCount: number): number {
 92	  if (alikeCount === ALIKE_COMPONENTS_PER_BLOCK) {
 93	    return COMPONENT_BLOCK_BASE_PREMIUM;
 94	  }
 95	  return alikeCount * COMPONENT_BASE_PREMIUM;
 96	}
 97	
 98	function componentsBasePremiumOf(components: readonly Item[]): number {
 99	  let total = 0;
100	  for (const alikeCount of countAlikeComponents(components).values()) {
101	    total += alikeComponentsBasePremiumOf(alikeCount);
102	  }
103	  return total;
104	}
105	
106	function isCursed(item: Item): boolean {
107	  return item.cursed === true;
108	}
109	
110	function isHighlyEnchanted(item: Item): boolean {
111	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_SURCHARGE_LEVEL;
112	}
113	
114	function itemSpecificSurchargesOn(item: Item, itemBasePremium: number): number {
115	  const curse = isCursed(item) ? itemBasePremium * CURSE_SURCHARGE_RATE : 0;
116	  const highEnchantment = isHighlyEnchanted(item)
117	    ? itemBasePremium * HIGH_ENCHANTMENT_SURCHARGE_RATE
118	    : 0;
119	  return curse + highEnchantment;
120	}
121	
122	function riskAdjustedMainItemPremiumOf(mainItem: Item): number {
123	  const itemBasePremium = mainItemBasePremiumOf(mainItem);
124	  return itemBasePremium + itemSpecificSurchargesOn(mainItem, itemBasePremium);
125	}
126	
127	function riskAdjustedMainItemsPremiumOf(mainItems: readonly Item[]): number {
128	  return mainItems.reduce((sum, mainItem) => sum + riskAdjustedMainItemPremiumOf(mainItem), 0);
129	}
130	
131	function mainItemsBasePremiumOf(mainItems: readonly Item[]): number {
132	  return mainItems.reduce((sum, mainItem) => sum + mainItemBasePremiumOf(mainItem), 0);
133	}
134	
135	// The policy base premium is the sum of all item base premiums, before any
136	// item-specific surcharge. Policy-wide modifiers are percentages of it.
137	function policyBasePremiumOf(items: readonly Item[]): number {
138	  return mainItemsBasePremiumOf(mainItemsOf(items)) + componentsBasePremiumOf(componentsOf(items));
139	}
140	
141	// Only main items carry item-specific surcharges: components have no curse flag,
142	// enchantment level, or material in the MHPCO item model.
143	function riskAdjustedItemsPremiumOf(items: readonly Item[]): number {
144	  return (
145	    riskAdjustedMainItemsPremiumOf(mainItemsOf(items)) +
146	    componentsBasePremiumOf(componentsOf(items))
147	  );
148	}
149	
150	// Deliberately takes no customer: "first insurance" is a property of the quoted
151	// item, not of the customer's history. Each item in a quote is treated as a first
152	// insurance, so the surcharge applies even on a follow-up contract.
153	function firstInsuranceSurchargeOn(policyBasePremium: number): number {
154	  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
155	}
156	
157	function isLongStanding(customer: Customer): boolean {
158	  return customer.yearsWithMHPCO >= LONG_STANDING_MINIMUM_YEARS;
159	}
160	
161	function loyaltyDiscountOn(customer: Customer, policyBasePremium: number): number {
162	  return isLongStanding(customer) ? policyBasePremium * LOYALTY_DISCOUNT_RATE : 0;
163	}
164	
165	// A contract after the customer's first earns the follow-up discount; the first
166	// contract does not.
167	function followUpContractDiscountOn(precedingContracts: number, policyBasePremium: number): number {
168	  return precedingContracts > 0 ? policyBasePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0;
169	}
170	
171	// Policy-wide modifiers (first insurance, loyalty, follow-up contract) are
172	// percentages of the policy base premium; the net signed sum is what the premium
173	// carries.
174	function policyWideModifiersOn(
175	  customer: Customer,
176	  precedingContracts: number,
177	  policyBasePremium: number,
178	): number {
179	  return (
180	    firstInsuranceSurchargeOn(policyBasePremium) -
181	    loyaltyDiscountOn(customer, policyBasePremium) -
182	    followUpContractDiscountOn(precedingContracts, policyBasePremium)
183	  );
184	}
185	
186	function roundPremiumInOfficesFavour(premium: number): number {
187	  return Math.ceil(premium);
188	}
189	
190	export function quote(
191	  customer: Customer,
192	  items: readonly Item[],
193	  precedingContracts = 0,
194	): number {
195	  return roundPremiumInOfficesFavour(
196	    riskAdjustedItemsPremiumOf(items) +
197	      policyWideModifiersOn(customer, precedingContracts, policyBasePremiumOf(items)) +
198	      PROCESSING_FEE,
199	  );
200	}
201	
202	// Determined by the item's type alone. Premium modifiers (curse, high
203	// enchantment, the component block discount, and every policy-wide modifier)
204	// price risk, never insured worth, so none of them may reach this price-list
205	// lookup: a cursed sword with premium 165 G still has insurance value 1000 G.
206	function insuranceValueOf(item: Item): number {
207	  return isComponent(item)
208	    ? COMPONENT_INSURANCE_VALUE
209	    : listedPriceFor(MAIN_ITEM_INSURANCE_VALUE_PRICE_LIST, item);
210	}
211	
212	// The insurance sum is the sum of the items' unmodified insurance values: every
213	// insured entry counts once, so two swords sum to 2000 G. Because it carries no
214	// premium modifier, the cap derived from it cannot be raised by one.
215	export function insuranceSumOf(items: readonly Item[]): number {
216	  return items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
217	}

