// The single contract an outside caller addresses the MHPCO through. The office's
// domain modules are organised by policy -- pricing, settling, sequencing -- which
// is the right split for the rules but leaves a caller to discover the public
// contract by import-chasing three modules. This states it in one place: a
// transport adapter translates a document into a `Scenario`, hands it to
// `runScenario`, and translates the `StepResult[]` back, and needs no other name.
export type { Customer, Item } from "./claim-office.js";
export type { ClaimSettlement, Damage, Incident } from "./claim.js";
export type {
  ClaimStep,
  QuoteResult,
  QuoteStep,
  Scenario,
  Step,
  StepResult,
} from "./scenario.js";
export { runScenario } from "./scenario.js";
EOF
